  ["OPTION_TOOLTIP_COMPATIBILITY_SETTINGS"] = { "互換性の設定は、さまざまなクラッシュ、グラフィックの不具合、パフォーマンスの問題の診断と回避のために用意されています。ほとんどの場合、これらの機能を無効にするとパフォーマンスが下がったり、カクつきが出たり、画質が落ちたりします。特定の問題が起きている場合にのみ無効にしてください。", 0xa05da243, "." },
  ["OPTION_TOOLTIP_COMPAT_SETTING_ADV_WORK_SUBMIT"] = { "GPUへの処理送信に、より複雑な方法を使えるようにします。無効にするとフレームレートが不安定になったり下がったりすることがありますが、特定のハードウェア、ドライバー、OSの組み合わせで起きるクラッシュを避けられる場合があります。 ", 0xa6b018d5, "." },
  ["OPTION_TOOLTIP_COMPAT_SETTING_CMDLIST_MULTITHREADING"] = { "複数のCPUスレッドでゲームを描画できるようにします。無効にするとフレームレートが大きく下がる可能性が高いですが、クラッシュや表示の不具合を回避できる場合があります。 ", 0x4c52310c, "." },
  ["OPTION_TOOLTIP_COMPAT_SETTING_DEVICE_MULTITHREADING"] = { "テクスチャやシェーダーなどのGPUリソースを非同期で作成できるようにします。無効にするとカクつきが出る可能性が高いですが、非常に古いドライバーやハードウェアでのクラッシュや表示の問題を回避できる場合があります。", 0xeb3d6af3, "." },
  ["OPTION_TOOLTIP_COMPAT_SETTING_OPTIONAL_GPU_FEATURES"] = { "新しいGPU機能を使えるようにします。無効にすると、GPUが最低限の必須機能しか持たないものとして動作します。さまざまなグラフィック機能が無効になり、画質が下がる可能性が高いです。ドライバーの不具合や新しいGPU機能の問題を回避できる場合があります。", 0x5fd56ff4, "." },
  ["OPTION_TOOLTIP_COMPUTE_EFFECTS"] = { "ボリュメトリックフォグや一部のパーティクル効果など、コンピュートベースの効果の品質を設定します。古いグラフィックカードでは負荷が大きくなることがあります。", 0x5e9570ee, "." },
